const std=@import("std");const M=@import("simulation/microbes.zig");const P=M.Protection;const W=@import("simulation/wind_packet.zig");const S=@import("simulation/shared_soil.zig");
test "protected mutation exactly once on three paid child routes with legacy RNG"{
 const cfg=P.Config{.enabled=true,.law=1,.mutation_law=1,.stream_seed=42};const wind=@import("simulation/wind_genetics.zig").Config{.enabled=true,.law=1,.stream_seed=42};const root=M.RootMutation.Config{.enabled=true,.law=1,.stream_seed=42};
 for(0..3)|route|{var a=M.initialized(17);a.cohorts[0]=.{.biomass=0.2,.support_mass=0.05,.root_fraction=0.5,.organization=0.25,.lineage=1,.reproduction_credit=0.1};var b=M.initialized(18);var stats=M.Stats{.next_lineage=2};var olda=a;var oldb=b;var olds=stats;
  if(route==0){try std.testing.expect(M.prepareProtectedPacket(&a,0,&b,&stats,true,root,wind,cfg));try std.testing.expect(M.prepareCombinedPacket(&olda,0,&oldb,&olds,true,root,wind));}else if(route==1){try std.testing.expect(M.reproduceProtectedLarge(&a,0,&b,&stats,root,wind,cfg));try std.testing.expect(M.reproduceCombinedLarge(&olda,0,&oldb,&olds,root,wind));}else{try std.testing.expect(W.launchProtected(&a,0,&b,&stats,2,1,true,wind,root,cfg).?.arrived);try std.testing.expect(W.launchCombined(&olda,0,&oldb,&olds,2,1,true,wind,root).?.arrived);}
  try std.testing.expectEqual(P.allocation(0,42,1,2,1),b.cohorts[0].protective_investment);try std.testing.expectEqual(@as(f32,-1),b.cohorts[0].protective_clock);var normalized=b;normalized.cohorts[0].protective_investment=0;try std.testing.expectEqualDeep(olda,a);try std.testing.expectEqualDeep(oldb,normalized);try std.testing.expectEqualDeep(olds,stats);
 }
 var d=M.initialized(17);d.cohorts[0]=.{.biomass=0.2,.lineage=1,.reproduction_credit=0.1};var t=M.initialized(18);var st=M.Stats{.next_lineage=2};const before=d;const failed=W.launchProtected(&d,0,&t,&st,2,1,false,wind,root,cfg).?;try std.testing.expect(!failed.arrived and failed.carbon_paid>0 and d.cohorts[0].biomass<before.cohorts[0].biomass);try std.testing.expectEqual(before.rng,d.rng);try std.testing.expectEqual(@as(f32,0),M.biomass(t));
}
test "finite elapsed guards and overshoot active reset do not double debit"{
 var c=M.initialized(42);c.cohorts[0]=.{.biomass=0.02,.support_mass=0.005,.root_fraction=0.5,.organization=0.25,.lineage=1,.protective_investment=0.5};const original=c;var env=M.Environment{.temperature=263,.depth_km=0,.light=1,.carbon_available=1,.oxygen_carbon_capacity=1};for([_]f32{0,-1,std.math.nan(f32),std.math.inf(f32)})|dt|{try std.testing.expectEqual(@as(f32,0),M.protectBefore(&c,env,dt));try std.testing.expectEqualDeep(original,c);}
 const paid=M.protectBefore(&c,env,1440);try std.testing.expectEqual(original.cohorts[0].biomass-c.cohorts[0].biomass,paid);const entered=c;try std.testing.expectEqual(@as(f32,0),M.protectBefore(&c,env,1440));try std.testing.expectEqualDeep(entered,c);env.temperature=298;_=M.protectBefore(&c,env,8000);try std.testing.expectEqual(@as(f32,8000),c.cohorts[0].protective_clock);try std.testing.expect(M.validProtection(c.cohorts[0]));_=M.protectBefore(&c,env,1);try std.testing.expectEqual(@as(f32,-1),c.cohorts[0].protective_clock);const awake=c;_=M.protectBefore(&c,env,1440);try std.testing.expectEqualDeep(awake,c);
 var co=c.cohorts[0];co.protective_clock= -2;try std.testing.expect(!M.validProtection(co));co.protective_clock=std.math.nan(f32);try std.testing.expect(!M.validProtection(co));co.protective_investment=0;co.protective_clock=0;try std.testing.expect(!M.validProtection(co));
 std.debug.print("PROTECT_LAYOUT cohort{} cell{}\n",.{@sizeOf(M.Cohort),@sizeOf(M.Cell)});
}
test "shared-root demand matches actual final-demand rate in partial protection"{var cell=M.initialized(42);cell.cohorts[0]=.{.biomass=0.02,.support_mass=0.005,.root_fraction=0.5,.organization=0.25,.lineage=1,.protective_investment=0.5,.protective_clock=0};const env=M.Environment{.temperature=298,.depth_km=0,.light=1,.carbon_available=1,.oxygen_carbon_capacity=1,.immersion_physiology=true,.final_demand_physiology=true};const w=S.stepBorrowed(&cell,0.5,1,7.6695296e9,env,1440,10,0).?;try std.testing.expectApproxEqAbs(M.rootDemand(cell.cohorts[0],env,1440),w.demand[0],1e-16);try std.testing.expect(w.credits[0]>0);}
